mapper.update:
update biz_lesson
lesson_title = #{lessonTitle}, grade = #{grade}, entry_year = #{entryYear}, semester = #{semester}, lesson_num = #{lessonNum}, shuffle_mode = #{shuffleMode}, random_choice_count = #{randomChoiceCount}, random_judgment_count = #{randomJudgmentCount}, lesson_mode = #{lessonMode}, teacher_note = #{teacherNote}, auto_advance_enabled = #{autoAdvanceEnabled}, auto_advance_threshold_pct = #{autoAdvanceThresholdPct}, auto_advance_delay_hours = #{autoAdvanceDelayHours}, auto_advance_ready_time = #{autoAdvanceReadyTime}, creator_id = #{creatorId}, dept_id = #{deptId}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where lesson_id = #{lessonId}

mapper.select:
select auto_advance_enabled, auto_advance_threshold_pct, auto_advance_delay_hours,
       teacher_id as creator_id, dept_id, create_by, create_time, update_by, update_time
from biz_lesson_advance_policy
where teacher_id = #{teacherId}
  and dept_id = #{deptId}
limit 1

SELECT
    l.lesson_id,
    l.lesson_title,
    l.lesson_num,
    l.entry_year,
    l.create_time,
    CASE WHEN l.creator_id = #{userId} OR l.create_by = #{creatorName}
         THEN 'self' ELSE 'shared' END AS course_type,
    EXISTS (
        SELECT 1
        FROM biz_lesson_question lq
        INNER JOIN biz_question q ON q.question_id = lq.question_id
        WHERE lq.lesson_id = l.lesson_id
          AND q.question_type = 'practical'
    ) AS has_practical,
    IFNULL(l.lesson_mode, 'assessment') as lesson_mode
FROM biz_lesson l
WHERE l.dept_id = #{deptId}
  AND IFNULL(l.lesson_mode, 'assessment') <> 'attendance'
  AND l.entry_year = #{entryYear}
  AND (
      (l.entry_year = #{entryYear} AND (l.creator_id = #{userId} OR l.create_by = #{creatorName}))
      OR (
          l.entry_year = #{entryYear}
          AND EXISTS (
              SELECT 1
              FROM biz_lesson_assignment la
              INNER JOIN biz_teacher_class tc
                      ON tc.dept_id = la.dept_id
                     AND tc.entry_year = la.entry_year
                     AND tc.class_code = la.class_code
              WHERE la.lesson_id = l.lesson_id
                AND la.dept_id = #{deptId}
                AND la.entry_year = #{entryYear}
                AND tc.user_id = #{userId}
          )
      )
      OR EXISTS (
          SELECT 1
          FROM biz_lesson_guide_sheet_binding b
          INNER JOIN biz_lesson_assignment la ON la.lesson_id = b.lesson_id
          WHERE b.lesson_id = l.lesson_id
            AND b.is_current = 'Y'
            AND b.enabled = 'Y'
            AND la.dept_id = #{deptId}
            AND la.entry_year = #{entryYear}
            AND (
                l.creator_id = #{userId}
                OR l.create_by = #{creatorName}
                OR EXISTS (
                    SELECT 1
                    FROM biz_teacher_class tc
                    WHERE tc.user_id = #{userId}
                      AND tc.dept_id = la.dept_id
                      AND tc.entry_year = la.entry_year
                      AND tc.class_code = la.class_code
                )
            )
      )
      OR EXISTS (
          SELECT 1
          FROM biz_lesson_assignment_history h
          INNER JOIN biz_teacher_class tc
                  ON tc.dept_id = h.dept_id

                 AND tc.entry_year = h.entry_year COLLATE utf8mb4_general_ci
                 AND tc.class_code = h.class_code COLLATE utf8mb4_general_ci
          WHERE (h.lesson_id = l.lesson_id OR h.next_lesson_id = l.lesson_id)
            AND h.dept_id = #{deptId}
            AND h.entry_year = #{entryYear}
            AND tc.user_id = #{userId}
      )
      OR EXISTS (
          SELECT 1
          FROM biz_student_answer ans
          INNER JOIN biz_student s ON s.student_id = ans.student_id
          INNER JOIN sys_user su ON su.user_id = s.user_id
          INNER JOIN biz_teacher_class tc
                  ON tc.dept_id = su.dept_id
                 AND tc.entry_year = s.entry_year
                 AND tc.class_code = s.class_code
          WHERE ans.lesson_id = l.lesson_id
            AND su.dept_id = #{deptId}
            AND s.entry_year = #{entryYear}
            AND tc.user_id = #{userId}
      )
  )
ORDER BY l.create_time DESC, l.lesson_id DESC

SELECT IFNULL(MAX(lesson_num), 0)
FROM biz_lesson
WHERE entry_year = #{entryYear}
  AND create_by = #{creatorName}
  AND dept_id = #{deptId}
